'use strict';
const copy={de:{eyebrow:'LERNEN ÜBER SPRACHGRENZEN HINWEG',title:'Verstehen. Wiederholen. Weiterkommen.',intro:'Ein Lernablauf für internationale Studierende. Probiere eine Karte und einen kurzen Selbsttest aus.',tag:'Interaktiver Prototyp · Fiktive Beispieldaten',session:'DEINE LERNEINHEIT',topic:'Geschäftsprozesse',subtitle:'Von einer Anfrage zum Ergebnis.','progress-label':'Sitzungsfortschritt',reset:'Neu beginnen','read-label':'VERSTEHEN','lesson-title':'Was ist ein Geschäftsprozess?',lesson:'Ein Geschäftsprozess verbindet mehrere Tätigkeiten mit einem Ziel. Beispiel: Eine Bibliothek erhält eine Reservierung, prüft die Verfügbarkeit und stellt das Buch bereit.',translation:'FR · Un processus métier relie plusieurs activités pour atteindre un objectif.','card-label':'WIEDERHOLEN','card-hint':'KARTE UMDREHEN ↗','card-note':'Was bedeutet dieser Begriff?','quiz-label':'ANWENDEN',question:'Was ist das Ziel des Bibliotheksprozesses?','about-title':'Über diesen Prototyp',about:'Diese Vorschau zeigt den Lernablauf, ohne Konten, Uploads oder KI-Aufrufe. Eingaben bleiben in dieser Sitzung. StudyBridge entstand mit umfangreicher Unterstützung durch generative KI, darunter ChatGPT/Codex.',transparency:'KI-Unterstützung & Projektbeitrag ↗',answers:['Das reservierte Buch bereitstellen','Möglichst viele Formulare erzeugen','Die Anfrage ohne Ergebnis schließen'],correct:'Richtig. Das Ergebnis ist das bereitgestellte Buch. Ein Prozess hat ein fachliches Ziel.',wrong:'Noch nicht. Gesucht ist das Ergebnis für die anfragende Person: das bereitgestellte Buch.',front:'Geschäftsprozess',back:'Processus métier',activities:'Aktivitäten'},fr:{eyebrow:'APPRENDRE AU-DELÀ DES LANGUES',title:'Comprendre. Réviser. Progresser.',intro:'Un parcours de révision pour les étudiants internationaux. Essaie une carte et un court exercice.',tag:'Prototype interactif · Exemples fictifs',session:'TA SÉANCE',topic:'Processus métier',subtitle:'De la demande au résultat.','progress-label':'Progression de la séance',reset:'Recommencer','read-label':'COMPRENDRE','lesson-title':'Qu’est-ce qu’un processus métier ?',lesson:'Un processus métier relie plusieurs activités pour atteindre un objectif. Exemple : une bibliothèque reçoit une réservation, vérifie la disponibilité et prépare le livre.',translation:'DE · Ein Geschäftsprozess verbindet mehrere Tätigkeiten mit einem Ziel.','card-label':'RÉVISER','card-hint':'RETOURNER LA CARTE ↗','card-note':'Quel est le terme allemand ?','quiz-label':'APPLIQUER',question:'Quel est l’objectif du processus de réservation ?','about-title':'À propos de ce prototype',about:'Cette démonstration présente le parcours de révision sans compte, import ni appel IA. Les réponses restent dans la séance. StudyBridge a été réalisé avec une aide importante de l’IA générative, notamment ChatGPT/Codex.',transparency:'Utilisation de l’IA et contribution au projet ↗',answers:['Mettre le livre réservé à disposition','Produire le plus de formulaires possible','Clore la demande sans résultat'],correct:'Exact. Le résultat est le livre mis à disposition. Un processus poursuit un objectif métier.',wrong:'Pas encore. Le résultat attendu par la personne est la mise à disposition du livre.',front:'Processus métier',back:'Geschäftsprozess',activities:'activités'}};
let language='de',flipped=false,cardDone=false,quizDone=false,selected=null;
const el=id=>document.getElementById(id);
function render(){const t=copy[language];document.documentElement.lang=language;for(const [k,v] of Object.entries(t))if(el(k))el(k).textContent=v;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===language)));el('flashcard').setAttribute('aria-label',language==='de'?'Lernkarte umdrehen':'Retourner la carte');el('card-text').textContent=flipped?t.back:t.front;el('card-note').textContent=flipped?(language==='de'?'Begriff auf Französisch':'Terme en allemand'):t['card-note'];el('progress').value=Number(cardDone)+Number(quizDone);el('progress-text').textContent=`${Number(cardDone)+Number(quizDone)} / 2 ${t.activities}`;el('answers').replaceChildren(...t.answers.map((answer,i)=>{const b=document.createElement('button');b.type='button';b.textContent=answer;b.setAttribute('aria-pressed',String(selected===i));if(selected!==null&&(i===0||selected===i))b.classList.add(i===0?'correct':'wrong');b.addEventListener('click',()=>{selected=i;quizDone=i===0;render()});return b}));el('feedback').textContent=selected===null?'':selected===0?t.correct:t.wrong}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{language=b.dataset.lang;render()}));el('flashcard').addEventListener('click',()=>{flipped=!flipped;cardDone=true;render()});el('reset').addEventListener('click',()=>{flipped=cardDone=quizDone=false;selected=null;render()});render();
